<?php
namespace Modules\LeaveManagement\Models;
use Illuminate\Database\Eloquent\Model;
class LeaveRecord extends Model { protected $table='leave_records'; protected $fillable=['request_id','personnel_id','personnel_code','personnel_name','status','leave_type','object_type','rank','position','enlistment_date','unit_id','unit_name','service_years','base_days','travel_days','extra_days','extra_reasons','total_days','start_date','end_date','leave_year','locality_id','locality_path','note','admin_note','replacement_personnel_id','replacement_personnel_name','replacement_position','proposed_by_user_id','proposed_by_username','proposed_by_display_name','decided_by_user_id','decided_by_username','decided_at','archived_at']; protected $casts=['start_date'=>'date','end_date'=>'date','enlistment_date'=>'date','extra_reasons'=>'array','decided_at'=>'datetime','archived_at'=>'datetime']; public function request(){return $this->belongsTo(LeaveRequest::class,'request_id');} public function personnel(){return $this->belongsTo(LeavePersonnel::class,'personnel_id');} public function decidedBy(){return $this->belongsTo(\App\Models\User::class,'decided_by_user_id');} }
